"""Native finite quintic width/offset tapers at explicitly declared seams.

Both halves meet at the same midpoint dimensions with zero first and second
dimensional derivatives. The crown law and source Section dimensions stay
unchanged. Quintic peak derivative 15/8 sets the minimum physical taper length.
"""


def parameters(g, sources, paths, iteration, width, offset):
    def meta(name, kind='FLOAT'):
        return g.sample(paths, g.named(name, kind), iteration, kind)
    values, envelope = {}, []
    for side in ('start', 'end'):
        base = 'st_path_'+side+'_transition'
        field = g.named(base)
        enabled = g.all(g.sample(paths, field.node.outputs['Exists'], iteration, 'BOOLEAN'),
                        g.compare(meta(base,'INT'),0,'GREATER_EQUAL','INT'))
        partner_edge = meta('st_path_'+side+'_seam_edge','INT')
        other_width = g.sample(sources,g.named('st_width','FLOAT'),partner_edge,'FLOAT','EDGE')
        other_offset = g.math('MULTIPLY',meta('st_path_'+side+'_seam_sign'),
            g.sample(sources,g.named('st_offset','FLOAT'),partner_edge,'FLOAT','EDGE'))
        joint_width = g.math('MULTIPLY',.5,g.math('ADD',width,other_width))
        joint_offset = g.math('MULTIPLY',.5,g.math('ADD',offset,other_offset))
        edge_delta = g.math('ADD',g.math('ABSOLUTE',g.math('SUBTRACT',offset,joint_offset)),
            g.math('MULTIPLY',.5,g.math('ABSOLUTE',g.math('SUBTRACT',width,joint_width))))
        half = g.math('MAXIMUM',meta(base+'_half'),g.math('DIVIDE',
            g.math('MULTIPLY',1.875,edge_delta),g.math('MAXIMUM',.001,meta(base+'_slope'))))
        for suffix, value, kind in (
            ('id',g.switch(enabled,-1,meta(base,'INT'),'INT'),'INT'),
            ('length',g.switch(enabled,0.,half),'FLOAT'),
            ('width',g.switch(enabled,width,joint_width),'FLOAT'),
            ('offset',g.switch(enabled,offset,joint_offset),'FLOAT'),
            ('partner',g.switch(enabled,-1,meta(base+'_partner','INT'),'INT'),'INT')):
            values[side+'_transition_'+suffix]=(value,kind)
        extent=g.math('ADD',g.math('ABSOLUTE',values[side+'_transition_offset'][0]),
                          g.math('MULTIPLY',.5,values[side+'_transition_width'][0]))
        envelope.append(extent)
    # A symmetric envelope bounds every intermediate signed edge offset.
    extent=g.math('MAXIMUM',g.math('ADD',g.math('ABSOLUTE',offset),g.math('MULTIPLY',.5,width)),
                  g.math('MAXIMUM',*envelope))
    active=g.either(*(g.compare(values[s+'_transition_id'][0],0,'GREATER_EQUAL','INT') for s in ('start','end')))
    return values,active,g.math('MULTIPLY',2.,extent)


def curvature_reach(g, curve, segment, values, width, offset):
    """Bound signed edge offsets over one complete cubic control span.

    Cumulative control chords are lower bounds on evaluated cubic arc length.
    A transition can be excluded only when the entire span is farther from its
    Section end than the taper extent, allowing for float accumulation. Otherwise
    its complete signed edge displacement remains in the bound. Independent
    interval addition also bounds overlapping tapers (which the surface rejects).
    This helper is used only by the free-terminal retry; accepted old curves keep
    their existing global-envelope check and exact construction.
    """
    index = g.node('GeometryNodeInputIndex', 'Control index for conservative taper distance').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Actual retained cubic controls').outputs[0]
    size = g.node('GeometryNodeAttributeDomainSize', 'Controls bounding taper distance')
    size.component = 'CURVE'; g.set(curve, size.inputs['Geometry'])
    count = size.outputs['Point Count']
    following = g.sample(curve, position, g.math('MINIMUM', g.math('ADD', index, 1.),
                                                g.math('SUBTRACT', count, 1.)), 'FLOAT_VECTOR')
    accumulate = g.node('GeometryNodeAccumulateField', 'Chord sums bound every intervening cubic arc')
    accumulate.domain = 'POINT'; accumulate.data_type = 'FLOAT'
    g.set(g.vector('DISTANCE', position, following), accumulate.inputs['Value'])
    prefix = g.sample(curve, accumulate.outputs['Trailing'], segment, 'FLOAT')
    suffix = g.sample(curve, g.math('SUBTRACT', accumulate.outputs['Total'],
                                  accumulate.outputs['Leading']), segment, 'FLOAT')
    total = g.sample(curve, accumulate.outputs['Total'], 0, 'FLOAT')
    magnitude = g.stat(curve, g.vector('LENGTH', position), output='Max')
    rounding = g.math('ADD', 1e-4, g.math('MULTIPLY', 16.*2.**-23,
        g.math('MULTIPLY', count, g.math('ADD', total, g.math('MULTIPLY', 2., magnitude)))))
    bounds = []
    for sign in (-.5, .5):
        edge = g.math('ADD', offset, g.math('MULTIPLY', sign, width))
        low, high = edge, edge
        for side, distance in (('start', prefix), ('end', suffix)):
            read = lambda name: values[side+'_transition_'+name][0]
            active = g.all(g.compare(read('id'), 0, 'GREATER_EQUAL', 'INT'),
                g.compare(read('length'), 0., 'GREATER_THAN'),
                g.compare(distance, g.math('ADD', read('length'), rounding), 'LESS_EQUAL'))
            joint = g.math('ADD', read('offset'), g.math('MULTIPLY', sign, read('width')))
            delta = g.switch(active, 0., g.math('SUBTRACT', joint, edge))
            low = g.math('ADD', low, g.math('MINIMUM', 0., delta))
            high = g.math('ADD', high, g.math('MAXIMUM', 0., delta))
        bounds.append(g.math('MAXIMUM', g.math('ABSOLUTE', low), g.math('ABSOLUTE', high)))
    return g.math('MAXIMUM', *bounds)


def surface(g, curves, iteration, meta, s, length, width, offset):
    from .path_station_nodes import arc_factor
    distance=g.math('MULTIPLY',arc_factor(g,curves,iteration,s),length)
    valid, active, code = [], [], 0
    result_width,result_offset=width,offset
    own_total=g.math('ADD',meta('start_transition_length'),meta('end_transition_length'))
    for side,d in (('start',distance),('end',g.math('SUBTRACT',length,distance))):
        prefix=side+'_transition_'
        tid=meta(prefix+'id','INT')
        # Old saved path records do not contain these attributes. Explicit
        # existence was captured when their curves were prepared.
        half=meta(prefix+'length')
        enabled=g.all(g.compare(tid,0,'GREATER_EQUAL','INT'),g.compare(half,0.,'GREATER_THAN'));active.append(enabled)
        t=g.math('MINIMUM',1.,g.math('MAXIMUM',0.,g.math('DIVIDE',d,g.math('MAXIMUM',half,1e-6))))
        smooth=g.math('MULTIPLY',g.math('POWER',t,3.),g.math('ADD',10.,
            g.math('MULTIPLY',t,g.math('ADD',-15.,g.math('MULTIPLY',6.,t)))))
        weight=g.switch(enabled,0.,g.math('SUBTRACT',1.,smooth))
        result_width=g.math('ADD',result_width,g.math('MULTIPLY',weight,g.math('SUBTRACT',meta(prefix+'width'),width)))
        result_offset=g.math('ADD',result_offset,g.math('MULTIPLY',weight,g.math('SUBTRACT',meta(prefix+'offset'),offset)))
        partner=meta(prefix+'partner','INT')
        other_length=meta('length',at=partner)
        other_total=g.math('ADD',meta('start_transition_length',at=partner),meta('end_transition_length',at=partner))
        room=g.all(
            g.compare(length,g.math('ADD',own_total,.001),'GREATER_THAN'),
            g.compare(other_length,g.math('ADD',other_total,.001),'GREATER_THAN'))
        other_valid=meta('valid','BOOLEAN',partner)
        valid.append(g.either(g.boolean('NOT',enabled),g.all(room,other_valid)))
        code=g.switch(g.all(enabled,g.boolean('NOT',other_valid)),code,meta('diagnostic_code','INT',partner),'INT')
        code=g.switch(g.all(enabled,g.boolean('NOT',room)),code,65,'INT')
    enabled=g.either(*active)
    # Preserve byte-identical arithmetic on existing non-transition fixtures.
    return (g.switch(enabled,width,result_width),g.switch(enabled,offset,result_offset),
            g.all(*valid),distance,code)


def face_identity(g, meta, length):
    """Classify face centers using interpolated physical distance, never IDs."""
    distance=g.named('st_transition_distance','FLOAT')
    result=-1
    for side,d in (('start',distance),('end',g.math('SUBTRACT',length,distance))):
        tid=meta(side+'_transition_id','INT');half=meta(side+'_transition_length')
        enabled=g.all(g.compare(tid,0,'GREATER_EQUAL','INT'),g.compare(half,0.,'GREATER_THAN'),
                      g.compare(d,half,'LESS_THAN'))
        result=g.switch(enabled,result,tid,'INT')
    return result
